import React, { useState } from "react";
import { motion, type SVGMotionProps } from "motion/react";
const Box = () => {
  const [hovered, setHovered] = useState<boolean>(false);
  return (
    <div
      className=""
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <motion.button
        key={String(hovered)}
        animate={{
          scale: hovered ? 0.8 : 1,
          x: hovered ? [0, -30, 30, -30, 30, 0] : 0,
          y: hovered ? [0, 30, -30, 30, -30, 0] : 0,
        }}
        exit={{
          filter: "none",
          scale: 1,
          x: 0,
          y: 0,
        }}
        transition={{
          duration: 0.2,
          x: {
            duration: 0.2,
            repeat: Infinity,
            repeatType: "loop",
          },
          y: {
            duration: 0.2,
            repeat: Infinity,
            repeatType: "loop",
          },
          scale: {
            duration: 0.2,
          },
          filter: {
            duration: 0.2,
          },
        }}
        className="relative active:scale-95 active:transition-all cursor-pointer"
      >
        <Tape
          width={96}
          className="absolute top-26.5 left-1/2 -translate-x-1/2 z-10"
        />

        <BoxTop
          width={368}
          className="absolute top-1/2 -translate-y-1/2 left-1/2 -translate-x-1/2 z-5"
        />
        <BoxBottom
          width={366}
          className="absolute top-0 left-1/2 -translate-x-1/2 z-1"
        />
      </motion.button>
    </div>
  );
};

